/* Start mission is a little fishing boat that blinks a teal glow to draw the eye.
   The button itself is see-through: ::before is the hull, ::after the cabin,
   and the mast is a thin background stripe. The glow is a drop-shadow so it
   follows the boat's outline instead of a rectangle. */
#btn-start {
  position: relative; isolation: isolate;
  padding: 34px 40px 12px; border-radius: 0;
  background: linear-gradient(var(--text), var(--text)) no-repeat 64% 0 / 3px 26px;
  color: var(--navy);
  animation: start-blink 1.4s ease-in-out infinite;
}
#btn-start::before { /* hull, with a darker stripe at the waterline */
  content: ""; position: absolute; inset: 22px 0 0 0; z-index: -1;
  background: linear-gradient(var(--teal) 80%, #1fa892 80%);
  clip-path: polygon(0 8%, 100% 0, 88% 100%, 9% 100%);
}
#btn-start::after { /* cabin with a porthole */
  content: ""; position: absolute; left: 24%; bottom: calc(100% - 22px);
  width: 24%; max-width: 64px; height: 16px; border-radius: 4px 4px 0 0;
  background: radial-gradient(circle at 50% 55%, var(--navy-2) 3px, transparent 4px) var(--text);
}
#btn-start:hover, #btn-start:focus-visible { animation-play-state: paused; filter: brightness(1.1) drop-shadow(0 0 10px rgba(45, 224, 196, 0.6)); }
@keyframes start-blink {
  0%, 100% { filter: brightness(1) drop-shadow(0 0 0 rgba(45, 224, 196, 0)); }
  50% { filter: brightness(1.15) drop-shadow(0 0 12px rgba(45, 224, 196, 0.85)); }
}

