  content: ""; position: absolute; inset: 20px 0 0 0; z-index: -1;
  background: linear-gradient(var(--teal) 82%, #1fa892 82%);
  clip-path: polygon(0 6%, 100% 0, 89% 100%, 8% 100%);
}
