  content: ""; position: absolute; left: 24%; bottom: calc(100% - 20px);
  width: 40%; max-width: 140px; height: 30px;
  background:
    radial-gradient(circle, var(--navy-2) 3.5px, transparent 4.5px) no-repeat left calc(27% - 6px) bottom 2px / 12px 12px,
    linear-gradient(var(--text), var(--text)) no-repeat right 20% bottom / 4px 30px,
    linear-gradient(var(--text), var(--text)) no-repeat left bottom / 55% 16px;
}
